44	RunResult run_process(const std::vector<std::string>& argv, int timeout_ms) {
45	  RunResult r;
46	  if (argv.empty()) {
47	    r.spawn_failed = true;
48	    return r;
49	  }
50	
51	  int fds[2];
52	  if (pipe(fds) != 0) {
53	    r.spawn_failed = true;
54	    return r;
55	  }
56	
57	  pid_t pid = fork();
58	  if (pid < 0) {
59	    close(fds[0]);
60	    close(fds[1]);
61	    r.spawn_failed = true;
62	    return r;
63	  }
64	
65	  if (pid == 0) {  // child: stdout to the pipe, stdin/stderr to /dev/null
66	    close(fds[0]);
67	    dup2(fds[1], STDOUT_FILENO);
68	    int devnull = open("/dev/null", O_RDWR);
69	    if (devnull >= 0) {
70	      dup2(devnull, STDIN_FILENO);
71	      dup2(devnull, STDERR_FILENO);
72	      if (devnull > 2) close(devnull);
73	    }
74	    close(fds[1]);
75	    exec_or_die(argv);
76	  }
77	
78	  // parent
79	  close(fds[1]);
80	  int rfd = fds[0];
81	  const long deadline = now_ms() + timeout_ms;
82	  char buf[4096];
83	
84	  while (true) {
85	    long remaining = deadline - now_ms();
86	    if (remaining < 0) remaining = 0;
87	    struct pollfd pfd{rfd, POLLIN, 0};
88	    int pr = poll(&pfd, 1, static_cast<int>(remaining));
89	    if (pr < 0) {
90	      if (errno == EINTR) continue;
91	      break;
92	    }
93	    if (pr == 0) {  // timed out with no data ready
94	      kill(pid, SIGKILL);
95	      r.timed_out = true;
96	      break;
97	    }
98	    if (pfd.revents & (POLLIN | POLLHUP | POLLERR)) {
99	      ssize_t n = read(rfd, buf, sizeof(buf));
100	      if (n > 0) {
101	        r.out.append(buf, static_cast<size_t>(n));
102	      } else if (n == 0) {
103	        break;  // EOF: child closed stdout
104	      } else {
105	        if (errno == EINTR) continue;
106	        break;
107	      }
108	    }
109	    if (now_ms() >= deadline) {  // chatty child kept us past the deadline
110	      kill(pid, SIGKILL);
111	      r.timed_out = true;
112	      break;
113	    }
114	  }
115	
116	  close(rfd);
117	  int status = 0;
118	  waitpid(pid, &status, 0);
119	  // rc stays -1 (the default) when timed out or abnormally terminated.
120	  if (!r.timed_out && WIFEXITED(status)) r.rc = WEXITSTATUS(status);
121	  return r;
122	}
